/* Self-contained runtime: this permits reliable use when index.html is opened directly. */
const KEY='cardFlipHQ.v1', VERSION=1;
const CONDITION_OPTIONS=['Near Mint (NM)','Lightly Played (LP)','Moderately Played (MP)','Heavily Played (HP)','Damaged (DMG)'];
const GRADING_STATUS_OPTIONS=['Raw / Ungraded','PSA Graded','CGC Graded','Beckett / BGS Graded','ACE Graded','Other Grading Company'];
const ACCESSORY_OPTIONS=['Penny Sleeve','Toploader','Card Saver','Semi-Rigid Holder','Magnetic One-Touch Holder','Graded Slab','Team Bag','Deck Sleeve','Binder','Original Packaging','Promo Packaging','Display Case','Other','None'];
const defaults={version:VERSION,settings:{startingCapital:0,currency:'USD',targetProfit:2000,reserve:0,fees:{eBay:13.25,Whatnot:10,Local:0},pricing:{mode:'market',belowPercent:5,shippingEstimate:0}},inventory:[],watchlist:[],transactions:[],lastBackup:null};
const clone=v=>JSON.parse(JSON.stringify(v));
const money=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((Number(c)||0)/100);
const toCents=v=>{const n=Number(String(v??'').replace(/[$,\s]/g,''));return Number.isFinite(n)&&n>=0?Math.round(n*100):null};
const id=(p='rec')=>`${p}_${Date.now().toString(36)}${Math.random().toString(36).slice(2,7)}`;
function migrate(d){if(!d||typeof d!=='object'||Array.isArray(d))throw Error('Invalid data.');if(Number(d.version||1)>VERSION)throw Error('Data was created by a newer version.');const r={...clone(defaults),...d,version:VERSION,settings:{...defaults.settings,...d.settings,fees:{...defaults.settings.fees,...d.settings?.fees}}};['inventory','watchlist','transactions'].forEach(k=>{if(!Array.isArray(r[k]))r[k]=[];r[k].forEach(x=>{if(x&&typeof x==='object'&&!x.id)x.id=id(k.slice(0,3))})});return r}
function load(){try{const raw=localStorage.getItem(KEY);return raw?migrate(JSON.parse(raw)):clone(defaults)}catch(e){throw Error('Could not read Card Flip HQ data. '+e.message)}}
function save(d){try{d.version=VERSION;localStorage.setItem(KEY,JSON.stringify(d));return true}catch(e){throw Error('Could not save data (storage may be unavailable or full). '+e.message)}}
function validImport(raw){let d;try{d=JSON.parse(raw)}catch{throw Error('This file is not valid JSON.')}if(!d||typeof d!=='object'||!Array.isArray(d.inventory)||!Array.isArray(d.watchlist)||!Array.isArray(d.transactions))throw Error('Backup is missing required Card Flip HQ records.');for(const k of ['inventory','watchlist','transactions']){const seen=new Set;d[k].forEach(x=>{if(!x||typeof x!=='object')throw Error('Backup has an invalid record.');if(x.id&&seen.has(x.id))throw Error('Backup contains duplicate IDs.');if(x.id)seen.add(x.id)})}return migrate(d)}
function merge(a,b){const r=clone(a);['inventory','watchlist','transactions'].forEach(k=>{const used=new Set(r[k].map(x=>x.id));b[k].forEach(x=>{const y={...x};if(!y.id||used.has(y.id))y.id=id(k.slice(0,3));used.add(y.id);r[k].push(y)})});r.settings={...r.settings,...b.settings};return r}
const backupName=()=>`card-flip-hq-backup-${new Date().toISOString().slice(0,10)}.json`;
function inventoryCost(x){return(+x.acquisitionCost||0)*(+x.quantity||1)}
function daysHeld(x){const start=x.purchaseDate?new Date(x.purchaseDate):null;if(!start||isNaN(start))return '—';const end=x.status==='Sold'&&x.saleDate?new Date(x.saleDate):new Date();if(isNaN(end))return '—';return Math.max(0,Math.round((end-start)/86400000));}
function conditionLabel(x){const short=String(x.condition||'').match(/\(([^)]+)\)/)?.[1]||x.condition||'—';const graded=x.gradingStatus&&x.gradingStatus!=='Raw / Ungraded';if(!graded)return `<span class="cond">${esc(short)}</span>`;const g=[x.gradingCompany||x.gradingStatus.replace(' Graded',''),x.grade].filter(Boolean).join(' ');return `<span class="cond">${esc(short)}</span><br><span class="muted card-sub">${esc(g||'Graded')}</span>`;}
function soldProfit(x){return(+x.actualSalePrice||0)-inventoryCost(x)-(+x.sellingFees||0)-(+x.sellerShipping||0)-(+x.otherExpenses||0)}
function dealMath(d){const gross=+d.gross||0,asking=+d.asking||0,selling=(+d.platformFee||0)+(+d.processingFee||0)+(+d.shipping||0)+(+d.otherSelling||0),purchaseOther=(+d.purchaseTax||0)+(+d.travel||0),reserve=+d.reserve||0,target=+d.targetProfit||0,maxOffer=gross-selling-purchaseOther-reserve-target,profitAtAsk=gross-selling-asking-purchaseOther-reserve,costAtAsk=asking+purchaseOther;return{gross,asking,selling,purchaseOther,reserve,target,maxOffer,profitAtAsk,net:gross-selling,roi:costAtAsk?profitAtAsk/costAtAsk:0,margin:gross?profitAtAsk/gross:0,maxPercent:gross?maxOffer/gross:0,difference:asking-maxOffer,assessment:asking<=maxOffer?(asking<maxOffer*.9?'BUY':'NEGOTIATE'):'PASS'}}
function summarize(d){const inv=d.inventory||[],tx=d.transactions||[],active=inv.filter(x=>!['Sold','Written off'].includes(x.status)),sold=inv.filter(x=>x.status==='Sold'),revenue=sold.reduce((s,x)=>s+(+x.actualSalePrice||0),0),realized=sold.reduce((s,x)=>s+soldProfit(x),0),inventory=active.reduce((s,x)=>s+inventoryCost(x),0),contributions=tx.filter(x=>x.type==='Owner contribution').reduce((s,x)=>s+(+x.amount||0),0),withdrawals=tx.filter(x=>x.type==='Owner withdrawal').reduce((s,x)=>s+(+x.amount||0),0),nonOps=tx.filter(x=>['Marketplace fees','Payment processing','Shipping','Supplies','Refunds','Returns','Travel','Other business expenses'].includes(x.type)).reduce((s,x)=>s+(+x.amount||0),0),purchases=inv.reduce((s,x)=>s+inventoryCost(x),0),salesCash=sold.reduce((s,x)=>s+(+x.actualSalePrice||0)-(+x.sellingFees||0)-(+x.sellerShipping||0)-(+x.otherExpenses||0),0),month=new Date().toISOString().slice(0,7),ms=sold.filter(x=>String(x.saleDate||'').slice(0,7)===month);const summary={cash:(+d.settings.startingCapital||0)+contributions-withdrawals-purchases+salesCash-nonOps,inventory,estimatedUnsold:active.reduce((s,x)=>s+(+x.estimatedValue||0)*(+x.quantity||1),0),unrealized:active.reduce((s,x)=>{const e=+x.estimatedValue||0;return e>0?s+(e-(+x.acquisitionCost||0))*(+x.quantity||1):s},0),estInventoryCost:inv.reduce((s,x)=>{const c=+x.acquisitionCost||0;if(c>0)return s+inventoryCost(x);const est=+x.estimatedValue||+x.priceMarket||0;return s+est*(+x.quantity||1)},0),revenue,realized,operating:tx.filter(x=>['Marketplace fees','Payment processing','Shipping','Supplies','Travel','Other business expenses'].includes(x.type)).reduce((s,x)=>s+(+x.amount||0),0),records:inv.length,active:inv.filter(x=>x.status==='Listed').length,openDeals:(d.watchlist||[]).filter(x=>!['Purchased','Rejected','Expired'].includes(x.status)).length,contributions,withdrawals,monthlySales:ms.reduce((s,x)=>s+(+x.actualSalePrice||0),0),monthlyProfit:ms.reduce((s,x)=>s+soldProfit(x),0),avgProfit:sold.length?realized/sold.length:0,sellThrough:inv.length?sold.length/inv.length:null,holdingDays:sold.length?sold.reduce((s,x)=>s+(new Date(x.saleDate)-new Date(x.purchaseDate))/86400000,0)/sold.length:null,recent:inv.slice().sort((a,b)=>String(b.saleDate||b.purchaseDate||'').localeCompare(String(a.saleDate||a.purchaseDate||''))).slice(0,6)};summary.totalCapital=summary.cash+summary.inventory;return summary}

let data, page = 'dashboard';
// Keep page visibility reliable even if a cached stylesheet predates the .hidden rule.
const visibilityStyle=document.createElement('style');visibilityStyle.textContent='.hidden{display:none!important}';document.head.appendChild(visibilityStyle);
const $ = s => document.querySelector(s);
const pages = {dashboard:'Dashboard',calculator:'Deal Calculator',inventory:'Inventory',watchlist:'Deal Watchlist',ledger:'Sales & Expenses',growth:'Growth Tracker',settings:'Settings & Backups'};
// User text is escaped before it is placed in generated markup.
const esc = v => String(v ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const date = () => new Date().toISOString().slice(0,10);
const currency = v => money(Number(v)||0);
function note(message, bad=false){ const n=$('#notice'); n.textContent=message; n.style.color=bad?'#b52637':'#167044'; setTimeout(()=>{if(n.textContent===message)n.textContent='';},5000); }
function persist(){ try{save(data); return true;}catch(e){note(e.message,true);return false;} }
function amount(name,label, val=0, req=false){return `<label>${label}<input name="${name}" inputmode="decimal" data-money ${req?'required':''} value="${((Number(val)||0)/100).toFixed(2)}"></label>`}
function text(name,label,val='',extra='',inputExtra=''){return `<label ${extra}>${label}<input name="${name}" value="${esc(val)}" ${inputExtra}></label>`}
function select(name,label,options,val=''){
  const entries=options.map(x=>typeof x==='string'?{value:x,label:x}:{value:x.value,label:x.label});
  const selectedValue=String(val ?? '');
  const selected = entries.some(entry => entry.value === selectedValue || entry.label === selectedValue);
  const finalEntries = selected ? entries : [...entries,{value:selectedValue,label:selectedValue}];
  return `<label>${label}<select name="${name}">${finalEntries.map(({value,label})=>`<option value="${esc(value)}" ${((value===selectedValue)||(label===selectedValue))?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`;
}
function fieldValues(form){const o={}; new FormData(form).forEach((v,k)=>o[k]=v.trim ? v.trim() : v); o.accessoriesIncluded = Array.from(form.querySelectorAll('input[name="accessoriesIncluded"]:checked')).map(el => el.value); o.otherAccessoryDescription = form.querySelector('[name="otherAccessoryDescription"]')?.value.trim() || ''; form.querySelectorAll('[data-money]').forEach(e=>{let n=toCents(e.value); if(n===null) throw Error(`${e.closest('label').textContent.trim()} must be a non-negative amount.`);o[e.name]=n;}); return o;}
function setPage(p){
  if(!Object.prototype.hasOwnProperty.call(pages,p)){note('That page is unavailable.',true);return;}
  const target=$('#'+p),heading=$('#page-title'),sidebar=document.querySelector('aside');
  if(!target||!heading||!sidebar){note('Navigation could not find a required page element.',true);return;}
  page=p;
  Object.keys(pages).forEach(key=>{const section=$('#'+key);if(section)section.classList.toggle('hidden',key!==p);});
  $('#nav').querySelectorAll('[data-page]').forEach(button=>button.classList.toggle('active',button.dataset.page===p));
  heading.textContent=pages[p];render();sidebar.classList.remove('open');
}
function dl(filename, type, body){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csv(rows){return rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n');}
function photoDataUrl(file){return new Promise((resolve,reject)=>{if(!file||!file.type.startsWith('image/'))return reject(Error('Choose an image file.'));if(file.size>10*1024*1024)return reject(Error('Choose an image smaller than 10 MB.'));const reader=new FileReader();reader.onerror=()=>reject(Error('Could not read that image.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(Error('Could not process that image.'));image.onload=()=>{const max=1400,scale=Math.min(1,max/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82));};image.src=reader.result;};reader.readAsDataURL(file);});}
function mountPhotoPicker(form){if(form.dataset.photoPickerMounted)return;const reference=form.querySelector('[name="imageReference"]');if(!reference)return;form.dataset.photoPickerMounted='true';const wrap=document.createElement('div');wrap.className='inventory-photo span3';wrap.innerHTML='<label>Add inventory photo<input data-inventory-photo type="file" accept="image/*" capture="environment"></label><p class="muted">Optional. The image is resized and saved only in this browser with the inventory record.</p><img class="inventory-photo-preview hidden" alt="Inventory photo preview">';reference.closest('label').insertAdjacentElement('afterend',wrap);const preview=wrap.querySelector('img'),show=source=>{if(source){preview.src=source;preview.classList.remove('hidden');}else{preview.removeAttribute('src');preview.classList.add('hidden');}};show(reference.value);reference.addEventListener('input',()=>show(reference.value));wrap.querySelector('[data-inventory-photo]').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;try{show('');const value=await photoDataUrl(file);reference.value=value;show(value);note('Photo attached. It will save with this inventory record.');}catch(error){event.target.value='';show(reference.value);note(error.message,true);}});}
function storedEditionOptions(value){try{const options=Array.isArray(value)?value:JSON.parse(value||'[]');return Array.isArray(options)?options.filter(option=>typeof option==='string'):[];}catch{return [];}}
function printingOptionsForCard(card){const keys=Object.keys(card.tcgplayer?.prices||{}).map(key=>key.toLowerCase()),options=[];if(keys.some(key=>key.includes('1stedition')))options.push('1st Edition');if(card.set?.name==='Base Set'&&keys.some(key=>key.includes('1stedition')))options.push('Shadowless');if(keys.some(key=>key.includes('unlimited')))options.push('Unlimited');if(keys.some(key=>key==='normal'||key.includes('holo')||key.includes('reverse')))options.push('Normal');if(!options.length)options.push('Normal');options.push('Other');return [...new Set(options)];}
function mountEditionPicker(form){if(form.dataset.editionPickerMounted)return;const variant=form.querySelector('[name="variant"]');if(!variant)return;form.dataset.editionPickerMounted='true';const recordId=form.querySelector('[name="id"]')?.value,existing=recordId?data.inventory.find(record=>record.id===recordId):null,pending=window.cardFlipPendingPrinting;const options=[...new Set([...(pending?.options||[]),...storedEditionOptions(existing?.editionOptions),existing?.editionPrinting||'', 'Normal','Other'].filter(Boolean))];const selected=pending?.selected||existing?.editionPrinting||'Normal',wrap=document.createElement('label'),select=document.createElement('select'),hidden=document.createElement('input');wrap.className='edition-printing';wrap.append('Edition / Printing');select.name='editionPrinting';options.forEach(option=>{const item=document.createElement('option');item.value=option;item.textContent=option;item.selected=option===selected;select.append(item);});hidden.type='hidden';hidden.name='editionOptions';hidden.value=JSON.stringify(options);wrap.append(select,hidden);variant.closest('label').insertAdjacentElement('afterend',wrap);window.cardFlipPendingPrinting=null;}
function reverseHoloValue(record){if(record?.isReverseHolo==='Yes')return 'Yes';if(record?.isReverseHolo==='No')return 'No';return /reverse\s*holo/i.test(String(record?.variant||''))?'Yes':'No';}
function mountReverseHoloPicker(form){if(form.dataset.reverseHoloPickerMounted)return;const edition=form.querySelector('[name="editionPrinting"]'),variant=form.querySelector('[name="variant"]');if(!variant)return;form.dataset.reverseHoloPickerMounted='true';const recordId=form.querySelector('[name="id"]')?.value,existing=recordId?data.inventory.find(record=>record.id===recordId):null,wrap=document.createElement('label'),select=document.createElement('select');wrap.className='reverse-holo';wrap.append('Reverse holo');select.name='isReverseHolo';[['No','Not reverse holo'],['Yes','Reverse holo']].forEach(([value,label])=>{const item=document.createElement('option');item.value=value;item.textContent=label;item.selected=value===reverseHoloValue(existing);select.append(item);});wrap.append(select);(edition||variant.closest('label')).insertAdjacentElement('afterend',wrap);}
function decorateEditionLabels(){document.querySelectorAll('.row-select[data-select-id]').forEach(box=>{const record=data.inventory.find(item=>item.id===box.dataset.selectId),sub=box.closest('tr')?.querySelector('.card-sub');if(!sub)return;if(record?.editionPrinting&&!sub.querySelector('.edition-label')){const label=document.createElement('span');label.className='edition-label';label.textContent=` · ${record.editionPrinting}`;sub.append(label);}if(!sub.querySelector('.reverse-holo-label')){const label=document.createElement('span');label.className=`reverse-holo-label ${reverseHoloValue(record)==='Yes'?'yes':'no'}`;label.textContent=reverseHoloValue(record)==='Yes'?' · Reverse holo':' · Not reverse holo';sub.append(label);}});}
// Inventory forms are created dynamically inside the modal. Observe them so the upload control
// is added once without changing the existing storage schema or save workflow.
new MutationObserver(()=>{const form=$('#inventory-form');if(form){mountPhotoPicker(form);mountEditionPicker(form);mountReverseHoloPicker(form);}}).observe($('#modal-content'),{childList:true,subtree:true});
new MutationObserver(decorateEditionLabels).observe($('#inventory'),{childList:true,subtree:true});
function confirmAction(msg){return window.confirm(msg);}

function dashboard(){const s=summarize(data); const metrics=[['Starting capital',data.settings.startingCapital],['Available cash',s.cash],['Unsold inventory at cost',s.inventory],['Unsold est. value',s.estimatedUnsold],['Est. inventory cost',s.estInventoryCost],['Total business capital',s.totalCapital],['Realized profit',s.realized],['Unrealized potential profit',s.unrealized],['Sales revenue',s.revenue],['Operating expenses',s.operating],['Inventory records',s.records,'count'],['Active listings',s.active,'count'],['Open deals',s.openDeals,'count'],['This month: sales',s.monthlySales],['This month: profit',s.monthlyProfit]]; $('#dashboard').innerHTML=`<div class="actions"><button class="btn" data-go="inventory">Add inventory</button><button class="secondary" data-go="calculator">Analyze a deal</button><button class="secondary" data-go="ledger">Record transaction</button></div><div class="grid metrics" style="margin-top:17px">${metrics.map(x=>`<div class="card metric"><label>${x[0]}</label><strong>${x[2]==='count'?x[1]:currency(x[1])}</strong></div>`).join('')}</div><div class="split" style="margin-top:17px"><div class="panel"><h2>Recent purchases & sales</h2>${s.recent.length?`<div class="table-wrap"><table><tr><th>Item</th><th>Status</th><th>Amount</th></tr>${s.recent.map(x=>`<tr><td>${esc(x.cardName||x.dealName||'Untitled')}</td><td><span class="badge">${esc(x.status)}</span></td><td>${x.status==='Sold'?currency(x.actualSalePrice):currency(inventoryCost(x))}</td></tr>`).join('')}</table></div>`:'<div class="empty">No activity yet. Add an inventory record or analyze a prospective deal.</div>'}</div><div class="panel"><h2>Financial definition</h2><p class="muted">Realized profit includes sold inventory only: sale price less recorded cost of goods sold and selling expenses. Unsold inventory remains an asset at cost.</p><p class="muted">Local browser storage is device-specific. Export backups regularly.</p></div></div>`;}
function calculator(){ $('#calculator').innerHTML=`<div class="panel"><h2>Deal analysis</h2><p class="muted">All results are estimates. Fee defaults are editable in Settings; use either a preset or fixed manual fees, never both.</p><form id="deal-form" class="grid">${text('dealName','Deal name','','class="span2"')}${text('seller','Seller')} ${amount('asking','Seller asking price',0,true)}${amount('gross','Estimated realistic gross sales',0,true)}${select('feePreset','Fee assumption',['Manual','eBay','Whatnot','Local'],'Manual')}${amount('platformFee','Manual marketplace fee (fixed)',0)}${amount('processingFee','Manual payment fee (fixed)',0)}${amount('purchaseTax','Purchase tax')} ${amount('travel','Travel / acquisition expenses')}${amount('shipping','Shipping & packaging')} ${amount('otherSelling','Other anticipated selling costs')}${amount('reserve','Contingency reserve',data.settings.reserve)}${amount('targetProfit','Target profit',data.settings.targetProfit)}${amount('desiredRoi','Desired ROI (optional)')}<label class="span3">Notes<textarea name="notes"></textarea></label><div class="span3 actions"><button>Calculate</button><button type="button" class="secondary" id="save-deal">Save to watchlist</button></div></form></div><div class="panel" id="deal-result"><div class="empty">Enter a deal to see the maximum offer and expected profit.</div></div>`;}
function dealResult(d){const m=dealMath(d); return `<h2 class="${m.assessment==='BUY'?'buy':m.assessment==='PASS'?'pass':'neg'}">${m.assessment}</h2><p class="muted">${m.assessment==='PASS'?'Asking price is above your maximum offer.':m.assessment==='BUY'?'Asking price leaves a material cushion under your maximum offer.':'Asking price meets the target closely; negotiate to preserve a cushion.'} This recommendation depends on your estimates.</p><div class="grid metrics"><div class="card metric"><label>Maximum offer</label><strong>${currency(m.maxOffer)}</strong></div><div class="card metric"><label>Profit at asking</label><strong>${currency(m.profitAtAsk)}</strong></div><div class="card metric"><label>Net sale proceeds</label><strong>${currency(m.net)}</strong></div><div class="card metric"><label>Expected ROI</label><strong>${(m.roi*100).toFixed(1)}%</strong></div><div class="card metric"><label>Profit margin</label><strong>${(m.margin*100).toFixed(1)}%</strong></div><div class="card metric"><label>Asking − maximum</label><strong>${currency(m.difference)}</strong></div></div>`;}
function inventory(){const items=data.inventory; $('#inventory').innerHTML=`<div class="panel"><div class="toolbar"><div class="toolbar-group" id="inventory-actions"><button class="btn" data-modal="inventory">Add inventory</button><button type="button" class="secondary" data-modal="lot">Add lot</button><button type="button" class="secondary" data-refresh-all>Refresh prices</button></div><div class="toolbar-group filters"><input id="inventory-search" placeholder="Search cards, seller, ID" aria-label="Search inventory"><select id="inventory-status"><option value="">All statuses</option>${['Researching','Purchased','Listed','Sold','Returned','Written off'].map(x=>`<option>${x}</option>`).join('')}</select><select id="inventory-sort"><option value="newest">Newest first</option><option value="name">Name A–Z</option><option value="costDesc">Cost high–low</option><option value="costAsc">Cost low–high</option><option value="profitDesc">Profit high–low</option></select></div></div></div><div class="panel"><div class="bulk-bar hidden" id="bulk-bar"><span class="muted" id="bulk-count"></span><select id="bulk-status"><option value="">Set status…</option>${['Researching','Purchased','Listed','Sold','Returned','Written off'].map(x=>`<option>${x}</option>`).join('')}</select><button type="button" class="secondary" data-bulk-apply>Apply</button><button type="button" class="danger" data-bulk-delete>Delete</button>${window.ebayUI?window.ebayUI.bulkButtons():''}</div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="inventory-select-all" aria-label="Select all"></th><th>Card / ID</th><th>Status</th><th>Condition</th><th>Qty owned</th><th>Qty sold</th><th>Days held</th><th>Cost</th><th>Est. price</th><th>Sale</th><th>Profit</th><th></th></tr></thead><tbody id="inventory-rows"></tbody></table></div></div>`; renderInventoryRows(items);}
function updateBulkBar(){const bar=$('#bulk-bar');if(!bar)return;const boxes=[...document.querySelectorAll('.row-select')];const count=boxes.filter(cb=>cb.checked).length;bar.classList.toggle('hidden',!count);const all=$('#inventory-select-all');if(all)all.checked=boxes.length>0&&boxes.every(cb=>cb.checked);const countEl=$('#bulk-count');if(countEl)countEl.textContent=count?count+' selected':'';}
function renderInventoryRows(items){const q=($('#inventory-search')?.value||'').toLowerCase(), st=$('#inventory-status')?.value||''; const list=items.filter(x=>(!st||x.status===st)&&JSON.stringify(x).toLowerCase().includes(q));const sortBy=$('#inventory-sort')?.value||'newest';if(sortBy==='name')list.sort((a,b)=>String(a.cardName||'').localeCompare(String(b.cardName||'')));else if(sortBy==='costDesc')list.sort((a,b)=>inventoryCost(b)-inventoryCost(a));else if(sortBy==='costAsc')list.sort((a,b)=>inventoryCost(a)-inventoryCost(b));else if(sortBy==='profitDesc')list.sort((a,b)=>(b.status==='Sold'?soldProfit(b):-Infinity)-(a.status==='Sold'?soldProfit(a):-Infinity));else list.sort((a,b)=>String(b.purchaseDate||'').localeCompare(String(a.purchaseDate||''))); $('#inventory-rows').innerHTML=list.length?list.map(x=>`<tr><td><input type="checkbox" class="row-select" data-select-id="${x.id}" aria-label="Select record"></td><td><div class="card-cell">${x.imageReference?`<img class="card-thumb" src="${esc(x.imageReference)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.opacity='0'">`:`<span class="card-thumb card-thumb-empty">🃏</span>`}<div class="card-id"><strong>${esc(x.cardName||'Untitled')}</strong><span class="muted card-sub">${[x.set,x.cardNumber?'#'+x.cardNumber:''].filter(Boolean).map(esc).join(' · ')}${x.set||x.cardNumber?' · ':''}${esc(x.id)}${x.lotName?' · '+esc(x.lotName):''}</span>${window.ebayUI?window.ebayUI.badge(x):''}</div></div></td><td><span class="badge badge-${String(x.status||'').toLowerCase().replace(/\s+/g,'-')}">${esc(x.status)}</span></td><td>${conditionLabel(x)}</td><td>${esc(x.quantity)}</td><td>${x.status==='Sold'?esc(x.quantity):'0'}</td><td>${daysHeld(x)}</td><td>${currency(inventoryCost(x))}</td><td>${priceCell(x)}</td><td>${x.status==='Sold'?currency(x.actualSalePrice):'—'}</td><td>${x.status==='Sold'?currency(soldProfit(x)):'—'}</td><td class="actions-cell">${window.ebayUI?window.ebayUI.rowButton(x):''}<button class="row-btn" data-price-toggle="${x.id}">Price</button><button class="row-btn" data-edit-inv="${x.id}">Edit</button><button class="row-btn row-btn-danger" data-delete-inv="${x.id}">Delete</button></td></tr>${openPricing.has(x.id)?`<tr class="price-detail-row"><td colspan="12">${priceDetailsHtml(x)}</td></tr>`:''}`).join(''):'<tr><td colspan="12" class="empty">No matching inventory records.</td></tr>';updateBulkBar();}
function inventoryForm(item={}){const statuses=['Researching','Purchased','Listed','Sold','Returned','Written off']; const selectedCondition=item.condition||'Near Mint (NM)'; const selectedGrading=item.gradingStatus||'Raw / Ungraded'; const selectedAccessories=Array.isArray(item.accessoriesIncluded)?item.accessoriesIncluded:[]; const otherAccessory=String(item.otherAccessoryDescription||''); const showGrading=selectedGrading !== 'Raw / Ungraded'; const showOtherAccessory=selectedAccessories.includes('Other')||Boolean(otherAccessory); const spMode=item.salePriceMode||((+item.targetSalePrice)>0?'manual':'auto'); const spState=spMode==='manual'?'Manually set':item.priceMarket!=null?`Auto · TCG market ${currency(item.priceMarket)}`:'Auto · no TCG price yet'; return `<h2>${item.id?'Edit':'Add'} inventory</h2><form id="inventory-form" class="grid"><input name="id" type="hidden" value="${esc(item.id||'')}">${text('cardName','Card or lot name',item.cardName,'class="span2"')}${text('pokemon','Pokémon',item.pokemon)}${text('set','Set',item.set)}${text('releaseYear','Release year',item.releaseYear)}${text('cardNumber','Card number',item.cardNumber)}${text('language','Language',item.language||'English')}${text('variant','Variant / rarity',item.variant)}${select('condition','Condition',CONDITION_OPTIONS.map(option=>({value:option,label:option})),selectedCondition)}${select('gradingStatus','Grading Status',GRADING_STATUS_OPTIONS.map(option=>({value:option,label:option})),selectedGrading)}<div class="grading-fields ${showGrading?'':'hidden'}"><div class="span3 grid"><label>Grading Company<input name="gradingCompany" value="${esc(item.gradingCompany || (selectedGrading !== 'Raw / Ungraded' ? selectedGrading.replace(' Graded','') : '') )}"></label><label>Grade<input name="grade" value="${esc(item.grade || '')}" placeholder="PSA 10, BGS 9.5, CGC 10"></label><label>Certification Number<input name="certificationNumber" value="${esc(item.certificationNumber || '')}" placeholder="Optional"></label></div></div>${text('authentication','Authentication / verification notes',item.authentication,'class="span2"')}${text('quantity','Quantity',item.quantity||1)}${text('purchaseDate','Purchase date',item.purchaseDate||date(),'','type="date"')}${text('seller','Seller / source',item.seller)}${amount('acquisitionCost','Acquisition cost per unit',item.acquisitionCost)}${amount('targetSalePrice','My sale price',item.targetSalePrice)}<div class="sale-price-meta"><span class="muted card-sub" id="sale-price-state">${spState}</span><input type="hidden" name="salePriceMode" value="${esc(spMode)}"><button type="button" class="row-btn" data-use-tcg-price>Use Latest TCG Price</button></div>${amount('estimatedValue','Estimated market value per unit',item.estimatedValue)}${select('platform','Platform',['','eBay','Whatnot','Local','Other'],item.platform)}${text('listingUrl','Listing URL',item.listingUrl,'class="span2"')}${select('status','Status',statuses,item.status||'Purchased')}<label class="quantity-sold-field ${item.status==='Sold'?'':'hidden'}">Quantity sold<input name="quantitySold" inputmode="numeric" value="${esc(item.quantity||1)}"></label>${text('saleDate','Sale date',item.saleDate,'','type="date"')}${amount('actualSalePrice','Actual sale price',item.actualSalePrice)}${amount('sellingFees','Selling fees',item.sellingFees)}${amount('sellerShipping','Shipping & packaging paid',item.sellerShipping)}${amount('otherExpenses','Other sale expenses',item.otherExpenses)}${text('imageReference','Image reference URL/path',item.imageReference,'class="span2"')}${text('listingDate','Listing date',item.listingDate,'','type="date"')}${select('shippingStatus','Shipping status',['','Pending shipment','Shipped','Delivered'],item.shippingStatus||'')}${text('shippedDate','Shipped date',item.shippedDate,'','type="date"')}${amount('researchPrice','Researched price',item.researchPrice)}${text('researchSource','Research source',item.researchSource)}${text('researchDate','Research date',item.researchDate,'','type="date"')}<div class="span3"><label>Accessories Included</label><div class="accessory-dropdown"><button type="button" class="accessory-toggle" data-accessory-toggle>${selectedAccessories.length?esc(selectedAccessories.join(', ')):'Select accessories…'}</button><div class="accessory-menu hidden">${ACCESSORY_OPTIONS.map(option=>`<label class="accessory-option"><input type="checkbox" name="accessoriesIncluded" value="${esc(option)}" ${selectedAccessories.includes(option)?'checked':''}>${esc(option)}</label>`).join('')}</div></div>${showOtherAccessory?`<label class="accessory-other">Other accessory description<input name="otherAccessoryDescription" value="${esc(otherAccessory)}" placeholder="Custom accessory description"></label>`:`<label class="accessory-other hidden">Other accessory description<input name="otherAccessoryDescription" value="${esc(otherAccessory)}" placeholder="Custom accessory description"></label>`}</div>${window.ebayUI?window.ebayUI.extraFields(item):''}<label class="span3">Notes<textarea name="notes">${esc(item.notes)}</textarea></label><div class="span3 actions"><button>Save inventory</button></div></form>`;}
const openPricing=new Set();
const PRICE_SOURCE='Pokémon TCG API · TCGplayer data';
function priceAge(ts){const t=new Date(ts).getTime();if(!t)return 'never';const m=Math.max(0,Math.round((Date.now()-t)/60000));if(m<1)return 'just now';if(m<60)return m+'m ago';const h=Math.round(m/60);if(h<48)return h+'h ago';return Math.round(h/24)+'d ago';}
function isStale(ts){return !ts||(Date.now()-new Date(ts).getTime())>7*86400000;}
function pickPriceVariant(card,variantText){const all=card.tcgplayer?.prices||{};const keys=Object.keys(all);if(!keys.length)return{key:'',prices:null,certainty:'unmatched',note:'Source supplied no prices for this card.'};const v=String(variantText||'').toLowerCase();let key='';if(/reverse/.test(v)&&all.reverseHolofoil)key='reverseHolofoil';else if(/holo/.test(v))key=all.holofoil?'holofoil':(all.unlimitedHolofoil?'unlimitedHolofoil':(all['1stEditionHolofoil']?'1stEditionHolofoil':''));if(!key)key=all.normal?'normal':keys[0];const certain=keys.length===1||/reverse|holo|common|uncommon|rare/.test(v);return{key,prices:all[key],certainty:certain?'exact':'partial',note:certain?'':`Variant not recorded — used "${key}" pricing.`};}
function applyCardPrice(rec,card){const picked=pickPriceVariant(card,rec.variant||rec.cardName||'');rec.priceCardId=card.id;rec.priceVariant=picked.key||'';const p=picked.prices||{};if(p.market!=null)rec.priceMarket=Math.round(p.market*100);['low','mid','high'].forEach(k=>{if(p[k]!=null)rec['price'+k[0].toUpperCase()+k.slice(1)]=Math.round(p[k]*100)});rec.priceSource=PRICE_SOURCE;rec.priceUpdatedAt=new Date().toISOString();rec.priceMatch=p.market!=null?picked.certainty:'unmatched';rec.priceNote=picked.note||'';if(p.market!=null&&rec.salePriceMode!=='manual'){rec.targetSalePrice=rec.priceMarket;rec.salePriceMode='auto';}if(p.market==null)rec.priceNote='No market price supplied for this printing.';if(rec.gradingStatus&&rec.gradingStatus!=='Raw / Ungraded'&&rec.priceMatch!=='unmatched'){rec.priceMatch='partial';rec.priceNote=(rec.priceNote?rec.priceNote+' ':'')+`Source has no graded prices — this is a raw-card reference, not a ${esc(rec.gradingCompany||rec.gradingStatus)} ${esc(rec.grade||'graded')} price.`;}}
function priceEstimate(x){const pr=data.settings.pricing||{mode:'market',belowPercent:5,shippingEstimate:0};const market=+x.priceMarket||0;let mode=pr.mode||'market';const feePct=x.platform&&data.settings.fees[x.platform]!=null?+data.settings.fees[x.platform]:0;const ship=+pr.shippingEstimate||0;const cost=inventoryCost(x);let suggested=null,targetMet=null;const myPrice=+x.targetSalePrice||0;if(myPrice>0){suggested=myPrice;mode='my price';}else if(mode==='custom'){suggested=null;}else if(mode==='below'){suggested=market?Math.round(market*(100-(+pr.belowPercent||0))/100):null;}else if(mode==='target'){const target=+data.settings.targetProfit||0,f=feePct/100;suggested=(market||cost)?Math.ceil((cost+target+ship)/((1-f)>0?(1-f):1)):null;targetMet=market?market>=suggested:null;}else suggested=market||null;if(suggested==null||!suggested)return{available:false,mode};const fees=Math.round(suggested*feePct/100),net=suggested-fees-ship,profit=net-cost;return{available:true,suggested,fees,ship,net,profit,margin:suggested?profit/suggested:null,mode,feePct,targetMet,market};}
function priceCell(x){const e=priceEstimate(x);if(!e.available)return '<span class="muted">Price unavailable</span>';const stale=isStale(x.priceUpdatedAt);return `<strong>${currency(e.suggested)}</strong><br><span class="muted card-sub">${(e.mode==='custom'||e.mode==='my price')?'my sale price':esc(priceAge(x.priceUpdatedAt))+(stale?' · <span class="stale">stale</span>':'')}</span>`;}
function priceDetailsHtml(x){const e=priceEstimate(x);const graded=x.gradingStatus&&x.gradingStatus!=='Raw / Ungraded';const condUsed=graded?`${esc(x.gradingCompany||x.gradingStatus)} ${esc(x.grade||'')} — raw-card reference only`:`${esc(x.condition||'Unknown condition')}${x.condition&&x.condition!=='Near Mint (NM)'?' — general market reference, no condition-specific price supplied':''}`;const match=x.priceMatch||'unmatched';const row=(l,v)=>`<div><label>${l}</label><strong>${v}</strong></div>`;return `<div class="price-detail-head"><h3>Pricing details</h3><button type="button" class="row-btn" data-refresh-price="${x.id}">Refresh price</button></div><p class="price-note">Estimate only — never confused with your actual cost or completed sale price. Refreshing never changes acquisition cost, condition, custom prices, or sale records.</p><div class="price-grid">${row('Pricing source',esc(x.priceSource||'—'))}${row('Source card ID',esc(x.priceCardId||'—'))}${row('Variant priced',esc(x.priceVariant||'—'))}${row('Condition / grade used',condUsed)}${row('Match quality',`<span class="price-flag ${match}">${match}</span>`)}${row('Last updated',x.priceUpdatedAt?`${esc(new Date(x.priceUpdatedAt).toLocaleString())} (${esc(priceAge(x.priceUpdatedAt))})${isStale(x.priceUpdatedAt)?' · <span class="stale">stale</span>':''}`:'Never')}${row('Market',x.priceMarket!=null?currency(x.priceMarket):'—')}${row('Low / Mid / High',x.priceLow!=null?`${currency(x.priceLow)} / ${currency(x.priceMid||0)} / ${currency(x.priceHigh||0)}`:'—')}${row('Suggested sale price',e.available?currency(e.suggested)+' · '+({market:'market',below:'below market',custom:'custom',target:'profit target','my price':'my sale price'}[e.mode]||e.mode):'Price unavailable')}${row('Est. selling fees',e.available?currency(e.fees)+` (${x.platform?esc(x.platform)+' '+e.feePct+'%':'no platform set — 0%'})`:'—')}${row('Est. shipping & packaging',e.available?currency(e.ship):'—')}${row('Est. net proceeds',e.available?currency(e.net):'—')}${row('Est. net profit',e.available?currency(e.profit):'—')}${row('Est. profit margin',e.available&&e.margin!=null?(e.margin*100).toFixed(1)+'%':'—')}</div>${e.targetMet===false?`<p class="price-note stale">Profit target not met at the current market price (${currency(e.market)} &lt; needed ${currency(e.suggested)}).</p>`:''}${x.priceNote?`<p class="price-note">${esc(x.priceNote)}</p>`:''}<p class="price-note">Source B (TCGplayer direct API): not configured. It requires a TCGplayer developer account and a small server-side proxy to hold the client secret — browser-only code cannot keep credentials private, and this app intentionally stores no secrets.</p>`;}
async function fetchCardJson(url){const key=(data.settings.pokemonApiKey||'').trim();const opts=key?{headers:{'X-Api-Key':key}}:{};let lastErr;for(let attempt=0;attempt<2;attempt++){try{const resp=await fetch(url,opts);if(resp.ok)return await resp.json();if(resp.status===429||resp.status>=500){lastErr=new Error('Card database temporarily unavailable (rate limit or server error) — try again in a minute.');}else{throw new Error(`Card database request failed (${resp.status}).`);}}catch(e){if(e.message&&e.message.includes('request failed'))throw e;lastErr=lastErr||new Error('Card database unreachable — check your internet connection.');}if(attempt===0)await new Promise(res=>setTimeout(res,1200));}throw lastErr;}
async function refreshPriceCore(rec,interactive){try{let card=null;if(rec.priceCardId){card=(await fetchCardJson(`https://api.pokemontcg.io/v2/cards/${encodeURIComponent(rec.priceCardId)}`)).data;}else{const clean=s=>String(s||'').replace(/[:"'&!()\[\]]/g,' ').replace(/\s+/g,' ').trim();const qv=s=>/[.\s]/.test(s)?`"${s}"`:s;const nm=clean(rec.cardName||rec.pokemon),num=clean(rec.cardNumber),st=clean(rec.set);const queries=[];const full=[];if(nm)full.push(`name:${qv(nm)}`);if(num)full.push(`number:${qv(num)}`);if(st)full.push(`set.name:${qv(st)}`);if(full.length)queries.push(full.join(' '));const nn=[];if(nm)nn.push(`name:${qv(nm)}`);if(num)nn.push(`number:${qv(num)}`);if(nn.length&&nn.join(' ')!==queries[0])queries.push(nn.join(' '));if(nm&&`name:${qv(nm)}`!==queries[queries.length-1])queries.push(`name:${qv(nm)}`);if(!queries.length){rec.priceMatch='unmatched';rec.priceNote='Not enough card details to search for a price.';return false;}let cards=null,lastErr=null;for(const q of queries){try{cards=(await fetchCardJson(`https://api.pokemontcg.io/v2/cards?${new URLSearchParams({q,pageSize:'10'})}`)).data||[];break;}catch(e){lastErr=e;}}if(!cards)throw lastErr||new Error('Card database unavailable.');if(!cards.length){rec.priceMatch='unmatched';rec.priceNote='No matching printing found in the card database.';return false;}const exactish=cards.filter(c=>String(c.number||'').toLowerCase()===num.toLowerCase()&&(!st||(c.set?.name||'').toLowerCase()===st.toLowerCase()));if(exactish.length===1)card=exactish[0];else if(cards.length===1)card=cards[0];else{rec.priceMatch='uncertain';rec.priceNote=`${cards.length} printings matched — pick the correct one; no price was applied.`;if(interactive){window.pricePickContext={recordId:rec.id,cards};showModal(pricePickHtml(rec,cards));}return false;}}applyCardPrice(rec,card);return rec.priceMatch!=='unmatched';}catch(e){rec.priceNote=`Price update failed: ${e.message}`;return false;}}
async function refreshPrice(recordId){const rec=data.inventory.find(r=>r.id===recordId);if(!rec)return;note('Updating price…');const ok=await refreshPriceCore(rec,true);persist();renderInventoryRows(data.inventory);note(ok?'Price updated.':(rec.priceNote||'Price could not be matched.'),!ok);}
async function refreshAllPrices(){const targets=data.inventory.filter(x=>!['Sold','Written off'].includes(x.status));if(!targets.length){note('No active inventory to price.',true);return;}let ok=0,fail=0,streak=0;for(let i=0;i<targets.length;i++){note(`Refreshing prices ${i+1}/${targets.length}…`);if(await refreshPriceCore(targets[i],false)){ok++;streak=0;}else{fail++;streak++;}if(streak>=3){note(`Stopped early: the card database seems unavailable (${ok} updated, ${targets.length-i-1} skipped).`,true);persist();renderInventoryRows(data.inventory);return;}if(i<targets.length-1)await new Promise(res=>setTimeout(res,600));}persist();renderInventoryRows(data.inventory);note(`Prices refreshed: ${ok} updated${fail?`, ${fail} need attention`:''}.`);}
function pricePickHtml(rec,cards){return `<h2>Choose the exact printing</h2><p class="muted">${esc(rec.cardName||'This card')} matched ${cards.length} printings and prices differ between them. No price was applied yet — select the exact printing.</p><div class="quick-results">${cards.map((card,index)=>`<article class="quick-card"><img src="${esc(card.images?.small||'')}" alt="" loading="lazy" referrerpolicy="no-referrer"><div><strong>${esc(card.name||'')}</strong><p>${esc(card.set?.name||'Unknown set')} · #${esc(card.number||'—')}</p><p class="muted">${esc(formatCardMeta(card))}</p></div><button type="button" class="secondary" data-price-pick="${index}">Use this printing</button></article>`).join('')}</div>`;}
function watchlist(){const rows=[...data.watchlist].sort((a,b)=>(b.profitAtAsk||0)-(a.profitAtAsk||0)); $('#watchlist').innerHTML=`<div class="panel"><button class="btn" data-modal="watch">Add prospective deal</button></div><div class="panel"><div class="table-wrap"><table><tr><th>Listing</th><th>Status</th><th>Asking</th><th>Max offer</th><th>Expected profit</th><th>Found</th><th></th></tr>${rows.length?rows.map(x=>`<tr><td><strong>${esc(x.dealName||x.listingTitle||'Untitled')}</strong><br><span class="muted">${esc(x.seller||'')}</span></td><td><span class="badge">${esc(x.status||'Researching')}</span></td><td>${currency(x.asking)}</td><td>${currency(x.maxOffer)}</td><td>${currency(x.profitAtAsk)}</td><td>${esc(x.dateFound||'')}</td><td><button class="secondary" data-edit-watch="${x.id}">Edit</button> <button class="danger" data-delete-watch="${x.id}">Delete</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">No prospective deals saved.</td></tr>'}</table></div><p class="muted">Saved deals are your own records; Card Flip HQ does not scrape or verify live listings.</p></div>`;}
function watchForm(x={}){return `<h2>${x.id?'Edit':'Add'} watchlist deal</h2><form id="watch-form" class="grid"><input type="hidden" name="id" value="${esc(x.id||'')}">${text('listingTitle','Listing title',x.dealName||x.listingTitle,'class="span2"')}${text('seller','Seller',x.seller)}${text('listingUrl','Listing URL',x.listingUrl,'class="span2"')}${select('platform','Source platform',['','eBay','Whatnot','Local','Other'],x.platform)}${amount('asking','Asking price',x.asking)}${amount('gross','Estimated gross value',x.gross)}${amount('estimatedFees','Estimated fees & expenses',(x.selling||0)+(x.purchaseOther||0))}${amount('maxOffer','Maximum offer',x.maxOffer)}${amount('profitAtAsk','Expected profit',x.profitAtAsk)}${text('dateFound','Date found',x.dateFound||date(),'','type="date"')}${select('status','Status',['Researching','Contacted','Negotiating','Purchased','Rejected','Expired'],x.status||'Researching')}<label class="span3">Notes<textarea name="notes">${esc(x.notes)}</textarea></label><div class="span3"><button>Save deal</button></div></form>`;}
function lotForm(){return `<h2>Add lot purchase</h2><p class="muted">Enter the total lot price and the cards in it. The total is split evenly across every unit (rounded to the nearest cent, first cards absorb rounding). Each card becomes its own inventory record linked by a shared lot ID.</p><form id="lot-form" class="grid">${text('lotName','Lot name','','class="span2"')}${amount('lotTotal','Total lot price',0,true)}${text('seller','Seller / source')}${text('purchaseDate','Purchase date',date(),'','type="date"')}<label class="span3">Cards in lot — one per line, e.g. "Charizard x2"<textarea name="lotCards" placeholder="Charizard x2
Blastoise
Pikachu" required></textarea></label><div class="span3"><button>Add lot to inventory</button></div></form>`;}
function ledger(){const tx=[...data.transactions].sort((a,b)=>String(b.date).localeCompare(String(a.date))); const types=['Starting capital','Inventory purchase','Sales receipt','Marketplace fees','Payment processing','Shipping','Supplies','Refunds','Returns','Travel','Other business expenses','Owner contribution','Owner withdrawal']; $('#ledger').innerHTML=`<div class="panel"><button class="btn" data-modal="transaction">Record transaction</button><p class="muted">Inventory purchases and sales should normally be recorded through Inventory so costs and sold profit reconcile automatically. Use this ledger for cash events and operating expenses.</p></div><div class="panel"><div class="table-wrap"><table><tr><th>Date</th><th>Type</th><th>Amount</th><th>Inventory ID</th><th>Platform</th><th>Notes</th><th></th></tr>${tx.length?tx.map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.type)}</td><td>${currency(x.amount)}</td><td>${esc(x.inventoryId)}</td><td>${esc(x.platform)}</td><td>${esc(x.notes)}</td><td><button class="danger" data-delete-tx="${x.id}">Delete</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">No ledger entries yet.</td></tr>'}</table></div></div>`;}
function txForm(){const types=['Marketplace fees','Payment processing','Shipping','Supplies','Refunds','Returns','Travel','Other business expenses','Owner contribution','Owner withdrawal'];return `<h2>Record transaction</h2><form id="tx-form" class="grid">${text('date','Date',date(),'','type="date"')}${select('type','Type',types)}${amount('amount','Amount',0,true)}${text('inventoryId','Associated inventory / lot ID')} ${select('platform','Platform',['','eBay','Whatnot','Local','Other'])}<label class="span3">Notes<textarea name="notes"></textarea></label><div class="span3"><button>Record transaction</button></div></form>`;}
function growth(){const s=summarize(data); $('#growth').innerHTML=`<div class="grid metrics">${[['Initial capital',data.settings.startingCapital],['Owner contributions',s.contributions],['Available cash',s.cash],['Cash tied up in inventory',s.inventory],['Cumulative realized profit',s.realized],['Average profit / sold item',s.avgProfit],['Sell-through rate',s.sellThrough===null?'—':(s.sellThrough*100).toFixed(1)+'%'],['Average holding time',s.holdingDays===null?'—':s.holdingDays.toFixed(0)+' days']].map(x=>`<div class="card metric"><label>${x[0]}</label><strong>${typeof x[1]==='string'?x[1]:currency(x[1])}</strong></div>`).join('')}</div><div class="panel" style="margin-top:17px"><h2>Actual results, not forecasts</h2><p class="muted">ROI is realized profit divided by recorded inventory cost sold (and does not annualize limited history). Current inventory is held at acquisition cost; market estimates are not treated as profit.</p></div>`;}
function settings(){const s=summarize(data); $('#settings').innerHTML=`<div class="split"><div class="panel"><h2>Business defaults</h2><form id="settings-form" class="grid">${amount('startingCapital','Starting capital',data.settings.startingCapital)}${amount('targetProfit','Default target profit',data.settings.targetProfit)}${amount('reserve','Default risk reserve',data.settings.reserve)}${amount('eBay','eBay fee estimate (%)',data.settings.fees.eBay*100)}${amount('Whatnot','Whatnot fee estimate (%)',data.settings.fees.Whatnot*100)}${amount('Local','Local sale fee estimate (%)',data.settings.fees.Local*100)}${select('pricingMode','Suggested sale price',[{value:'market',label:'At estimated market price'},{value:'below',label:'Slightly below market'},{value:'custom',label:'At my custom price'},{value:'target',label:'Maximum profit target'}],data.settings.pricing?.mode||'market')}${text('pricingBelow','Under-market percent (%)',data.settings.pricing?.belowPercent??5)}${amount('shippingEstimate','Estimated shipping & packaging per sale',data.settings.pricing?.shippingEstimate||0)}${text('pokemonApiKey','Pokémon TCG API key (optional — free key from pokemontcg.io raises rate limits)',data.settings.pokemonApiKey||'','class="span2"')}<div class="span3"><button>Save settings</button></div></form><p class="muted">USD only. Platform fees are estimates you control, not live fee data.</p></div><div class="panel"><h2>Backups & exports</h2><p class="muted">Last backup: ${data.lastBackup||'Not yet exported'}<br>${data.inventory.length} inventory records · ${data.transactions.length} transactions · ${data.watchlist.length} deals</p><div class="actions"><button class="secondary" id="export-json">Export JSON backup</button><button class="secondary" id="import-json">Import JSON</button><input id="import-file" type="file" accept="application/json,.json" hidden><button class="secondary" id="export-inventory">Inventory CSV</button><button class="secondary" id="export-tx">Transactions CSV</button><button class="danger" id="clear-data">Clear all data</button></div><p class="muted">localStorage is browser-specific and does not automatically synchronize between devices. Import validates before modifying current records; choose merge or replace after validation.</p></div></div>`;}
function saveInventoryForm(form){try{const x=fieldValues(form);x.quantity=Math.max(1,parseInt(x.quantity,10)||1);const soldQty=Math.min(x.quantity,Math.max(1,parseInt(x.quantitySold,10)||x.quantity));delete x.quantitySold;if(x.status==='Sold'&&!x.saleDate)throw Error('A sold item requires a sale date.');if(x.listingUrl&&!/^https?:\/\//i.test(x.listingUrl))throw Error('Listing URL must begin with http:// or https://.');const existing=x.id?data.inventory.find(record=>record.id===x.id):null;if(x.id&&!existing)throw Error('This inventory record could not be found.');let message='Inventory saved.';if(x.status==='Sold'&&soldQty<x.quantity){const remainingQty=x.quantity-soldQty;const priorStatus=existing?existing.status:'Purchased';const soldRecord={...x,quantity:soldQty};const remainingRecord={...x,id:id('inv'),quantity:remainingQty,status:priorStatus==='Sold'?'Purchased':priorStatus,saleDate:'',actualSalePrice:0,sellingFees:0,sellerShipping:0,otherExpenses:0};if(existing){data.inventory[data.inventory.findIndex(record=>record.id===x.id)]={...existing,...soldRecord};}else{soldRecord.id=id('inv');data.inventory.push(soldRecord);}data.inventory.push(remainingRecord);message=`Partial sale recorded: ${soldQty} sold, ${remainingQty} kept in inventory.`;}else{if(existing){data.inventory[data.inventory.findIndex(record=>record.id===x.id)]={...existing,...x};}else{data.inventory.push({...x,id:id('inv')});}}if(!persist())return;$('#modal').close();render();note(message);}catch(error){note(error.message||'Inventory could not be saved.',true);}}
function updateGradingFields(form){const gradingStatus=form.querySelector('[name="gradingStatus"]');const gradingFields=form.querySelector('.grading-fields');const gradingCompany=form.querySelector('[name="gradingCompany"]');const isGraded=gradingStatus && gradingStatus.value !== 'Raw / Ungraded';if(gradingFields)gradingFields.classList.toggle('hidden',!isGraded);if(gradingCompany && isGraded && !gradingCompany.value){gradingCompany.value = gradingStatus.value.replace(' Graded','');}}
function syncAccessorySelection(form,changed){const boxes=Array.from(form.querySelectorAll('input[name="accessoriesIncluded"]'));const otherField=form.querySelector('[name="otherAccessoryDescription"]');const otherWrap=otherField?.closest('.accessory-other');const noneBox=boxes.find(box=>box.value==='None');if(changed&&changed.checked){if(changed.value==='None'){boxes.filter(box=>box.value!=='None').forEach(box=>box.checked=false);}else if(noneBox){noneBox.checked=false;}} if(otherField){const otherChecked = boxes.some(box=>box.value==='Other' && box.checked); if(otherWrap)otherWrap.classList.toggle('hidden',!otherChecked); } const toggle=form.querySelector('[data-accessory-toggle]');if(toggle){const chosen=boxes.filter(box=>box.checked).map(box=>box.value);toggle.textContent=chosen.length?chosen.join(', '):'Select accessories…';} }
function showModal(html){$('#modal-content').innerHTML=html;const inventoryFormElement=$('#inventory-form');if(inventoryFormElement){const saveButton=inventoryFormElement.querySelector('button:not([type])');if(saveButton)saveButton.type='submit';updateGradingFields(inventoryFormElement);syncAccessorySelection(inventoryFormElement);inventoryFormElement.querySelector('[name="gradingStatus"]').addEventListener('change',()=>updateGradingFields(inventoryFormElement));const statusSelect=inventoryFormElement.querySelector('[name="status"]');const qtySoldField=inventoryFormElement.querySelector('.quantity-sold-field');if(statusSelect&&qtySoldField){statusSelect.addEventListener('change',()=>qtySoldField.classList.toggle('hidden',statusSelect.value!=='Sold'));}const spInput=inventoryFormElement.querySelector('[name="targetSalePrice"]');const spHidden=inventoryFormElement.querySelector('[name="salePriceMode"]');const spStateEl=inventoryFormElement.querySelector('#sale-price-state');if(spInput&&spHidden){spInput.addEventListener('input',()=>{spHidden.value='manual';if(spStateEl)spStateEl.textContent='Manually set';});}inventoryFormElement.querySelectorAll('input[name="accessoriesIncluded"]').forEach(box=>box.addEventListener('change',()=>syncAccessorySelection(inventoryFormElement,box)));const accessoryToggle=inventoryFormElement.querySelector('[data-accessory-toggle]');const accessoryMenu=inventoryFormElement.querySelector('.accessory-menu');if(accessoryToggle&&accessoryMenu){accessoryToggle.addEventListener('click',event=>{event.stopPropagation();accessoryMenu.classList.toggle('hidden');});document.addEventListener('click',event=>{if(!event.target.closest('.accessory-dropdown'))accessoryMenu.classList.add('hidden');});}inventoryFormElement.addEventListener('submit',event=>{event.preventDefault();event.stopPropagation();saveInventoryForm(inventoryFormElement);});}$('#modal').showModal();}
function quickFillModal(){return `<h2>Quick Fill Card</h2><p class="muted">Search the Pokémon TCG database to prefill card details only. You still choose the condition, quantity, and purchase-price details yourself.</p><div class="quick-search"><label>Card name<input id="quick-name" placeholder="e.g. Lucario"></label><label>Collector number<input id="quick-number" placeholder="e.g. 126"></label><label>Set name<input id="quick-set" placeholder="e.g. Brilliant Stars"></label><div class="actions"><button type="button" class="btn" data-quick-search>Search cards</button><button type="button" class="secondary" data-quick-manual>Use manual entry</button></div></div><div class="quick-search-tips"><span>Popular:</span> <button type="button" class="tiny" data-quick-suggest="pikachu">Pikachu</button> <button type="button" class="tiny" data-quick-suggest="charizard">Charizard</button> <button type="button" class="tiny" data-quick-suggest="lucario">Lucario</button> <button type="button" class="tiny" data-quick-suggest="mew">Mew</button></div><div id="quick-status" class="muted" aria-live="polite"></div><div id="quick-results" class="quick-results"></div>`;}
function cleanQuickValue(value){return String(value||'').trim().replace(/[:"'&!()\[\]*]/g,' ').replace(/\s+/g,' ').trim();}
function quickQueries(){const name=cleanQuickValue($('#quick-name')?.value),number=cleanQuickValue($('#quick-number')?.value),set=cleanQuickValue($('#quick-set')?.value);const qv=s=>/[.\s]/.test(s)?`"${s}"`:s;const q=[];const full=[];if(name)full.push(`name:${qv(name)}`);if(number)full.push(`number:${qv(number)}`);if(set)full.push(`set.name:${qv(set)}`);if(full.length)q.push(full.join(' '));const nn=[];if(name)nn.push(`name:${qv(name)}`);if(number)nn.push(`number:${qv(number)}`);if(nn.length&&nn.join(' ')!==q[0])q.push(nn.join(' '));if(name&&`name:${qv(name)}`!==q[q.length-1])q.push(`name:${qv(name)}`);return q;} 
function quickQuery(){const name=cleanQuickValue($('#quick-name')?.value),number=cleanQuickValue($('#quick-number')?.value),set=cleanQuickValue($('#quick-set')?.value);const parts=[];if(name)parts.push(`name:${name}`);if(number)parts.push(`number:${number}`);if(set)parts.push(`set.name:${set}`);return parts.join(' ');}
function rankQuickCard(card){const name=(card.name||'').toLowerCase();const set=(card.set?.name||'').toLowerCase();const number=(card.number||'').toLowerCase();const searchName=cleanQuickValue($('#quick-name')?.value).toLowerCase();const searchSet=cleanQuickValue($('#quick-set')?.value).toLowerCase();const searchNumber=cleanQuickValue($('#quick-number')?.value).toLowerCase();let score=0;if(searchName && name.includes(searchName))score+=50;if(searchSet && set.includes(searchSet))score+=25;if(searchNumber && number.includes(searchNumber))score+=20;if(name===searchName)score+=30;if(set===searchSet)score+=15;return score;}
function formatCardMeta(card){const pieces=[];if(card.rarity)pieces.push(card.rarity);if(card.supertype)pieces.push(card.supertype);if(card.types?.length)pieces.push(card.types.join(' / '));const year=card.set?.releaseDate?.slice(0,4)||'Year unavailable';return pieces.length?`${pieces.join(' · ')} · ${year}`:`${year}`;}
async function searchQuickFill(){const queries=quickQueries(),status=$('#quick-status'),results=$('#quick-results');if(!queries.length){status.textContent='Enter at least one card name, collector number, or set name.';return;}status.textContent='Searching card database…';results.innerHTML='';let payload=null,lastErr=null;for(const query of queries){try{const response=await fetch(`https://api.pokemontcg.io/v2/cards?${new URLSearchParams({q:query,pageSize:'12',orderBy:'-set.releaseDate'})}`);if(response.ok){payload=await response.json();break;}lastErr=new Error(response.status===400?'Search terms were not understood — try a simpler name or number.':response.status===429||response.status>=500?'Database temporarily unavailable (rate limit or server error) — try again in a minute.':`Database request failed (${response.status}).`);}catch(e){lastErr=new Error('Database unreachable — check your internet connection.');}}if(!payload){status.textContent=`Card database unavailable: ${lastErr.message} You can still use manual entry.`;return;}try{const cards=(Array.isArray(payload.data)?payload.data:[]).filter((card,index,items)=>items.findIndex(item=>item.id===card.id)===index).sort((a,b)=>rankQuickCard(b)-rankQuickCard(a));if(!cards.length){status.textContent='No matching cards found. Try a broader search or use manual entry.';return;}status.textContent=`${cards.length} match${cards.length===1?'':'es'} found. Choose the exact printing.`;results.innerHTML=cards.map((card,index)=>`<article class="quick-card"><img src="${esc(card.images?.small||'')}" alt="" loading="lazy" referrerpolicy="no-referrer"><div><strong>${esc(card.name||'Unnamed card')}</strong><p>${esc(card.set?.name||'Unknown set')} · #${esc(card.number||'—')}</p><p class="muted">${esc(formatCardMeta(card))}</p></div><button type="button" class="secondary" data-card-select="${index}">Use this card</button></article>`).join('');window.cardFlipQuickCards=cards;}catch(error){status.textContent=`Card database unavailable: ${error.message} You can still use manual entry.`;}}
function applyQuickCard(card){if(!card)return;const name=card.name||'';const setName=card.set?.name||'';const releaseYear=card.set?.releaseDate?.slice(0,4)||'';const rarity=card.rarity||'';const subtypes=Array.isArray(card.subtypes)?card.subtypes.join(', '):'';const types=Array.isArray(card.types)?card.types.join(', '):'';const variantParts=[rarity,subtypes,types].filter(Boolean),editionOptions=printingOptionsForCard(card);window.cardFlipPendingPrinting={options:editionOptions,selected:editionOptions.includes('Normal')?'Normal':editionOptions[0]};showModal(inventoryForm({cardName:name,pokemon:card.supertype==='Pokémon'?name:'',set:setName,releaseYear:releaseYear,cardNumber:String(card.number||''),language:'English',variant:variantParts.join(' · '),imageReference:card.images?.large||card.images?.small||'',status:'Purchased'}));note('Card details filled. Choose the edition/printing, then add your purchase details before saving.');}
function addQuickFillButton(){const actions=$('#inventory-actions');if(actions&&!$('#quick-fill-card')){const button=document.createElement('button');button.type='button';button.id='quick-fill-card';button.className='secondary';button.dataset.quickFill='';button.textContent='Quick Fill';actions.appendChild(button);}}
