function submitDeal(form,saveWatch=false){const d=fieldValues(form); const preset=d.feePreset; if(preset!=='Manual'){d.platformFee=Math.round(d.gross*(data.settings.fees[preset]||0)/100); d.processingFee=0;} else {d.platformFee=0;d.processingFee=0;} const m=dealMath(d); $('#deal-result').innerHTML=dealResult(d); form.dataset.deal=JSON.stringify({...d,...m}); if(saveWatch){data.watchlist.push({id:id('watch'),...d,...m,dateFound:date(),status:'Researching'});persist();note('Deal saved to watchlist.');}}

