if(b.dataset.useTcgPrice!==undefined){const form=$('#inventory-form');if(!form)return;const recId=form.querySelector('[name="id"]')?.value;const rec=recId?data.inventory.find(r=>r.id===recId):null;const market=rec?.priceMarket;const spField=form.querySelector('[name="targetSalePrice"]');if(market==null){note('No TCG price available yet — refresh pricing first.',true);return;}const cur=spField?toCents(spField.value):null;if(!confirmAction(`Replace your price ${cur!=null?currency(cur):'—'} with the latest TCG market price ${currency(market)}? This returns the card to automatic pricing.`))return;if(spField)spField.value=(market/100).toFixed(2);const hidden=form.querySelector('[name="salePriceMode"]');if(hidden)hidden.value='auto';const stateEl=form.querySelector('#sale-price-state');if(stateEl)stateEl.textContent=`Auto · TCG market ${currency(market)}`;note('Sale price set to the latest TCG price.');return;}
