document.addEventListener('input',e=>{if(e.target.id==='inventory-search'||e.target.id==='inventory-status')renderInventoryRows(data.inventory)}); document.addEventListener('keydown',e=>{if(['quick-name','quick-number','quick-set'].includes(e.target?.id) && e.key==='Enter'){e.preventDefault();searchQuickFill();}}); document.addEventListener('change',e=>{if(e.target.id==='inventory-status'||e.target.id==='inventory-sort')renderInventoryRows(data.inventory); if(e.target.id==='inventory-select-all'){document.querySelectorAll('.row-select').forEach(cb=>cb.checked=e.target.checked);}if(e.target.id==='inventory-select-all'||(e.target.classList&&e.target.classList.contains('row-select')))updateBulkBar(); if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const incoming=validImport(r.result);if(confirmAction('Press OK to replace all current Card Flip HQ data. Press Cancel to merge safely (duplicate IDs will be reassigned).'))data=incoming;else data=merge(data,incoming);persist();render();note('Backup imported successfully.');}catch(err){note(err.message,true)}};r.readAsText(file);e.target.value='';}});
document.addEventListener('submit',e=>{e.preventDefault(); try{const f=e.target;if(f.id==='deal-form')submitDeal(f); else if(f.id==='inventory-form'){const x=fieldValues(f);x.quantity=Math.max(1,parseInt(x.quantity)||1); if(x.status==='Sold'&&!x.saleDate)throw Error('A sold item requires a sale date.'); if(x.listingUrl&& !/^https?:\/\//i.test(x.listingUrl))throw Error('Listing URL must begin with http:// or https://.'); if(x.id){const i=data.inventory.findIndex(z=>z.id===x.id);data.inventory[i]={...data.inventory[i],...x};}else data.inventory.push({...x,id:id('inv')});persist();$('#modal').close();render();note('Inventory saved.');} else if(f.id==='watch-form'){const x=fieldValues(f);if(x.id){const i=data.watchlist.findIndex(z=>z.id===x.id);data.watchlist[i]={...data.watchlist[i],...x};}else data.watchlist.push({...x,id:id('watch')});persist();$('#modal').close();render();note('Watchlist deal saved.');}else if(f.id==='tx-form'){const x=fieldValues(f);data.transactions.push({id:id('tx'),...x});persist();$('#modal').close();render();note('Transaction recorded.');}else if(f.id==='lot-form'){const x=fieldValues(f);const lines=String(x.lotCards||'').split(/\n+/).map(l=>l.trim()).filter(Boolean);const cards=lines.map(l=>{const m=l.match(/^(.*?)\s*[x\u00d7]\s*(\d+)$/i);return m?{name:m[1].trim(),qty:Math.max(1,parseInt(m[2],10))}:{name:l,qty:1};}).filter(c=>c.name);if(!cards.length)throw Error('Add at least one card line to the lot.');if(!(x.lotTotal>0))throw Error('Total lot price must be greater than zero.');const totalUnits=cards.reduce((s,c)=>s+c.qty,0);const lotId=id('lot');let usedCents=0,usedUnits=0;cards.forEach(c=>{usedUnits+=c.qty;const target=Math.round(x.lotTotal*usedUnits/totalUnits);const recordTotal=target-usedCents;usedCents=target;data.inventory.push({id:id('inv'),cardName:c.name,quantity:c.qty,acquisitionCost:Math.round(recordTotal/c.qty),lotId,lotName:x.lotName||'Lot purchase',seller:x.seller,purchaseDate:x.purchaseDate,status:'Purchased',condition:'Near Mint (NM)',gradingStatus:'Raw / Ungraded',accessoriesIncluded:[]});});persist();$('#modal').close();render();note(`Lot added: ${cards.length} record${cards.length===1?'':'s'}, ${totalUnits} unit${totalUnits===1?'':'s'}, cost allocated.`);}else if(f.id==='settings-form'){const x=fieldValues(f);data.settings={...data.settings,startingCapital:x.startingCapital,targetProfit:x.targetProfit,reserve:x.reserve,pokemonApiKey:x.pokemonApiKey,fees:{eBay:x.eBay/100,Whatnot:x.Whatnot/100,Local:x.Local/100},pricing:{mode:x.pricingMode,belowPercent:parseFloat(x.pricingBelow)||0,shippingEstimate:x.shippingEstimate}}; /* display values were cents, restore percentage */ data.settings.fees={eBay:x.eBay/100,Whatnot:x.Whatnot/100,Local:x.Local/100};persist();render();note('Settings saved.');}}catch(err){note(err.message,true);}});
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.quickFill!==undefined){showModal(quickFillModal());return;}if(button.dataset.quickSearch!==undefined){searchQuickFill();return;}if(button.dataset.quickManual!==undefined){showModal(inventoryForm());return;}if(button.dataset.quickSuggest!==undefined){const field=$('#quick-name');if(field){field.value=button.dataset.quickSuggest;searchQuickFill();}}if(button.dataset.cardSelect!==undefined){applyQuickCard(window.cardFlipQuickCards?.[Number(button.dataset.cardSelect)]);}});
render();
